import { CdkMenu, CdkMenuItem } from '@angular/cdk/menu';
import { NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  TemplateRef,
  booleanAttribute,
  computed,
  contentChildren,
  inject,
  input,
  model,
  output,
  signal,
  viewChild,
} from '@angular/core';
import { AvatarComponent } from '../avatar/avatar.component';
import { BadgeComponent } from '../badge/badge.component';
import { CsButtonDirective } from '../core/foundations/cs-button.directive';
import { IconComponent } from '../icon/icon.component';
import { CsBreakpointService } from '../core/platform/cs-breakpoint.service';
import { ShellSidenavMode } from './shell-sidenav-mode.type';

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'cs-shell',
  templateUrl: './shell.component.html',
  host: { class: 'cs-shell' },
  styleUrl: './shell.component.scss',
})
export class ShellComponent {
  private readonly breakpoints = inject(CsBreakpointService);
  readonly opened = model(false);
  readonly mode = input<ShellSidenavMode>('auto');
  readonly compact = computed(
    () => this.mode() === 'over' || (this.mode() === 'auto' && this.breakpoints.compact()),
  );
}

scss:
:host {
  display: grid;
  min-block-size: 100dvh;
  grid-template: 'top top' auto 'side main' 1fr / 16rem 1fr;
}
header {
  grid-area: top;
  position: sticky;
  inset-block-start: 0;
  z-index: 30;
}
aside {
  grid-area: side;
  background: var(--cs-ink);
  color: var(--cs-paper);
}
main {
  grid-area: main;
  min-inline-size: 0;
  padding: clamp(1rem, 3vw, 2.5rem);
}
.scrim {
  display: none;
}
@media (max-width: 767.98px) {
  :host {
    display: block;
  }
  aside {
    position: fixed;
    inset: 3.5rem auto 0 0;
    z-index: 40;
    inline-size: min(20rem, 85vw);
    transform: translateX(-105%);
    transition: transform var(--cs-duration);
  }
  aside.open {
    transform: none;
  }
  .scrim {
    display: block;
    position: fixed;
    inset: 3.5rem 0 0;
    z-index: 35;
    border: 0;
    background: #0008;
    inline-size: 100%;
  }
}
